# Created: 2026-07-31

"""`python -m stage2` — one Stage-2 sweep against a throwaway instance (plan T2.6, T2.8).

Run from `tests/e2e/` with the repo's venv. This is the only entry point that spends money, so
the cheap paths are first-class rather than afterthoughts (D24's mid-session decision made the
expensive combination the default one):

    python -m stage2 --tier 1                      # 8 use cases, the smoke tier
    python -m stage2 --only uc9 --repeats 5        # the prescribed post-fix proof
    python -m stage2 --max-spend-usd 3.00          # a hard stop, not a warning

Everything the sweep needs beyond the model is the Stage-1 harness, unchanged: the throwaway
instance (D6/D7), the committed fixture, the REST oracle. The **reset** uses the product's own
wipe and import — the same path the release ritual exercises by hand — and then *checks* that
the tree came back as the committed cast, because a use case whose fixture silently drifted
grades nothing.
"""

from __future__ import annotations

import argparse
import os
import sys
from pathlib import Path

from fixtures import cast
from harness.backup_dir import BackupDir
from harness.docker_util import ProbeError
from harness.gramps_instance import OWNER_PW, OWNER_USER, ROLE_OWNER, GrampsInstance
from harness.mcp_container import McpContainer, container_name, image_from_env
from harness.rest import GrampsRest
from harness.runid import new_runid, run_dir

from stage2 import gates, report, runner, sweep
from stage2 import state as state_mod
from stage2.catalog import load_all

REPO_ROOT = Path(__file__).resolve().parents[3]
FIXTURE = Path(__file__).resolve().parents[1] / "fixtures" / "synthetic-tree.gramps"
CONTAINER_BACKUP = "/backup"


def parse(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(prog="stage2", description="one real-model sweep")
    parser.add_argument("--tier", type=int, choices=(1, 2, 3), help="only this tier")
    parser.add_argument("--only", nargs="+", metavar="UC", help="only these use cases, by id")
    parser.add_argument(
        "--repeats", type=int, help="run each chosen use case exactly this often (no early stop)"
    )
    parser.add_argument(
        "--max-spend-usd", type=float, help="hard stop: the sweep ends rather than exceeding this"
    )
    parser.add_argument("--keep", action="store_true", help="leave the instance running")
    args = parser.parse_args(argv)
    if args.tier and args.only:
        parser.error("--tier and --only both choose the use cases; pick one")
    if args.repeats is not None and args.repeats < 1:
        parser.error("--repeats has to be at least 1")
    return args


def select(args: argparse.Namespace) -> list:
    cases = load_all()
    if args.only:
        return sweep.only(cases, args.only)
    return sweep.by_tier(cases, args.tier)


def stage_backup(root: Path) -> Path:
    """The mounted backup directory, holding exactly the inputs D17 declared.

    Not a copy of the tree fixture: `BackupDir` stages the whole committed manifest and
    verifies each file against its digest. Copying by hand is what left uc19 asking a
    correctly-wired server for a file nobody had put there, three paid runs in a row — and a
    second enumeration of the same list would fall behind it again.
    """
    backup = BackupDir(root / "backup")
    backup.reset()  # chmods the directory too: the container runs as a different uid
    return backup.path


def main(argv: list[str] | None = None) -> int:
    args = parse(argv)
    chosen = select(args)
    runid = new_runid()
    root = run_dir(REPO_ROOT, runid)
    backup = stage_backup(root)

    instance = GrampsInstance(runid)
    print(f"run {runid} → {root}", flush=True)
    instance.start()
    if instance.add_user(OWNER_USER, OWNER_PW, ROLE_OWNER)["rc"] != 0:
        raise ProbeError("could not create the owner user on the throwaway instance")

    image = image_from_env(runid, os.environ)
    rest = GrampsRest(instance.url, OWNER_USER, OWNER_PW)
    harness_mcp = _reset_container(instance, image, backup)
    driver = _runner(instance, image, backup, root, runid)

    try:
        driver.prepare()
        driven = sweep.Sweep(
            driver=driver,
            reset=lambda: _reset(harness_mcp, rest),
            capture=lambda: state_mod.capture(rest),
            backup_dir=backup,
            max_spend_usd=args.max_spend_usd,
        )
        verdicts = _sweep(driven, chosen, args)
        _write(root, verdicts, driven, runid)
        print(f"spent ${driven.spent:.4f} · report {root / 'summary.md'}", flush=True)
        if driven.aborted:
            # Exit 2, not 1: a harness fault is not a finding, and a caller that cannot tell
            # them apart would read an aborted sweep as the product having failed.
            print(f"ABORTED · {driven.aborted}", flush=True)
            return 2
        return 1 if any(verdict.reportable for verdict in verdicts) else 0
    finally:
        harness_mcp.close()
        if not args.keep:
            instance.teardown()


def _sweep(driven: sweep.Sweep, chosen: list, args: argparse.Namespace) -> list:
    if args.repeats:
        return driven.repeat_all(chosen, args.repeats)
    return driven.run(chosen)


def _reset_container(instance: GrampsInstance, image, backup: Path) -> McpContainer:
    """The harness's own container — separate from the one `claude` spawns for the model."""
    return McpContainer(
        container_name(instance.runid, "reset"),
        image.run_reference,
        {
            "GRAMPS_BASE_URL": instance.internal_url,
            "GRAMPS_USERNAME": OWNER_USER,
            "GRAMPS_PASSWORD": OWNER_PW,
            "GRAMPS_ENABLE_DESTRUCTIVE": "1",
            "GRAMPS_BACKUP_DIR": CONTAINER_BACKUP,
        },
        network=instance.network,
        mounts=((str(backup), CONTAINER_BACKUP),),
        runid=instance.runid,
    )


def _runner(instance: GrampsInstance, image, backup: Path, root: Path, runid: str):
    return runner.Runner(
        image=image,
        network=instance.network,
        gramps_env={
            "GRAMPS_BASE_URL": instance.internal_url,
            "GRAMPS_USERNAME": OWNER_USER,
            "GRAMPS_PASSWORD": OWNER_PW,
        },
        backup_dir=backup,
        run_root=root,
        runid=runid,
    )


def _reset(mcp: McpContainer, rest: GrampsRest) -> None:
    """Wipe, import, and prove the tree came back as the committed cast.

    The proof is not ceremony: every use case resolves its subjects against this tree, so a
    fixture that drifted turns 27 use cases into 27 unexplainable reds.
    """
    counts = rest.object_counts()
    total = sum(counts.values())
    if total:
        wiped = mcp.call(
            "gramps_delete_all_objects", {"confirm": True, "expected_count": total}, timeout=600
        )
        if wiped.is_error:
            raise ProbeError(f"the reset could not wipe the tree: {wiped.text[:400]}")

    imported = mcp.call("gramps_import_file", {"filename": FIXTURE.name}, timeout=600)
    if imported.is_error:
        raise ProbeError(f"the reset could not import the fixture: {imported.text[:400]}")

    restored = rest.object_counts()
    if restored != cast.COUNTS:
        raise ProbeError(
            f"the reset left {restored}, the committed cast is {cast.COUNTS} — every use case "
            "resolves its subjects against this tree, so grading anything now is guesswork"
        )


def _write(root: Path, verdicts: list, driven: sweep.Sweep, runid: str) -> None:
    (root / "summary.md").write_text(
        report.summary(
            verdicts,
            driven.graded,
            spent=driven.spent,
            budget=driven.max_spend_usd,
            stamp=runid,
            aborted=driven.aborted,
            stopped=driven.stopped,
        ),
        encoding="utf-8",
    )
    drafts = root / "drafts"
    for index, (title, body) in enumerate(report.drafts(verdicts, driven.graded), start=1):
        drafts.mkdir(exist_ok=True)
        (drafts / f"{index:02d}.md").write_text(f"# {title}\n\n{body}\n", encoding="utf-8")
    if drafts.exists():
        print(
            f"{len(list(drafts.iterdir()))} draft(s) in {drafts} — "
            f"nothing was filed; dedup against `gh issue list` on {gates.MARKER}",
            flush=True,
        )


if __name__ == "__main__":  # pragma: no cover - exercised by running it
    sys.exit(main())
